content.text:
    }
    if (limit <= max) {
        for (int k = 0; k < 64; ++k) {
            if (!cnt[k]) continue;
            u128_t cregion = region | (static_cast<u128_t>(k) << (128 - limit));
            int ci = exp_build(c, origin, cregion, limit, sorted, start[k], start[k + 1]);
            n.ckey.push_back(static_cast<uint8_t>(k));
            n.cidx.push_back(ci);
        }
    }
    int cc = static_cast<int>(n.ckey.size());
    n.type = (cc <= 2) ? TYPE1 : ((cc <= 6) ? TYPE2 : TYPE3);
    n.owned = static_cast<uint32_t>(n.lpos.size());
    for (int i = 0; i < cc; ++i) n.owned += c.nodes[n.cidx[i]].owned;
    if (n.owned != static_cast<uint32_t>(count)) throw std::runtime_error("owned mismatch");
    return idx;
}

void pack_inline(Row256& row, int& pos, const ScampPrefix& p, int origin) {
    uint64_t frag;
    uint32_t len;
    if (origin == 0) {
        frag = scamp_hi(p.addr);
        len = p.len;
    } else if (origin == 16) {
        frag = (scamp_hi(p.addr) & 0xFFFFFFFFFFFFULL) << 16;
        len = static_cast<uint32_t>(p.len) - 16u;
    } else {
        frag = scamp_lo(p.addr);
        len = static_cast<uint32_t>(p.len) - 64u;
    }
    pk_write(row, pos, frag, PK_INL_FRAG_BITS);
    pk_write(row, pos, len, PK_INL_LEN_BITS);
    pk_write(row, pos, p.hop, PK_INL_HOP_BITS);
}

